+/// Same result as [`reduce_step`]. `m * MODULUS[1] + m` is `m * 2^32`, so
+/// that product is written as shifts; the top product stays a multiply.
+#[inline(always)]
+fn reduce_step_mac(
+    m: u64,
+    a1: u64,
+    a2: u64,
+    a3: u64,
+    a4: u64,
+    carry: u64,
+) -> (u64, u64, u64, u64, u64) {
+    let (a1, c) = adc(a1, m << 32, 0);
+    let (a2, c) = adc(a2, m >> 32, c);
+    let (a3, c) = mac(a3, m, MODULUS[3], c);
+    let (a4, c) = adc(a4, c, carry);
+    (a1, a2, a3, a4, c)
+}

